/**
 * PHASE_4C837 P0-009 — Web PNR socket subscription manager.
 * Shared logic with mobile (services/pnrSocketClient); web-local copy for Next bundling.
 */

export type PnrSocketPayload = {
  pnr?: string;
  data?: unknown;
  message?: string;
};

export type PnrSocketCallbacks = {
  onPnrUpdate: (data: unknown) => void;
  onAutoRefreshStopped: (payload: PnrSocketPayload) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
};

export type PnrSocketLike = {
  on: (event: string, handler: (...args: any[]) => void) => void;
  off: (event: string, handler: (...args: any[]) => void) => void;
  emit: (event: string, payload?: unknown) => void;
};

export class PnrSocketSubscriptionManager {
  private activePnr: string | null = null;
  private subscribedPnr: string | null = null;

  constructor(
    private readonly getSocket: () => PnrSocketLike | null,
    private readonly callbacks: PnrSocketCallbacks
  ) {}

  setActivePnr(pnr: string | null) {
    this.activePnr = pnr;
  }

  getActivePnr(): string | null {
    return this.activePnr;
  }

  getSubscribedPnr(): string | null {
    return this.subscribedPnr;
  }

  /** Server room contract: pnr:{pnr} via subscribe:pnr */
  subscribe(pnr: string) {
    const socket = this.getSocket();
    if (!socket || !pnr) return;

    if (this.subscribedPnr && this.subscribedPnr !== pnr) {
      socket.emit('unsubscribe:pnr', this.subscribedPnr);
    }

    if (this.subscribedPnr !== pnr) {
      socket.emit('subscribe:pnr', pnr);
      this.subscribedPnr = pnr;
    }
  }

  unsubscribe(pnr?: string) {
    const target = pnr || this.subscribedPnr;
    const socket = this.getSocket();
    if (!socket || !target) return;

    socket.emit('unsubscribe:pnr', target);
    if (this.subscribedPnr === target) {
      this.subscribedPnr = null;
    }
  }

  /** After reconnect the server-side room membership is lost — force re-subscribe. */
  resubscribeOnConnect() {
    if (!this.activePnr) return;
    this.subscribedPnr = null;
    this.subscribe(this.activePnr);
  }

  shouldApplyUpdate(payload: PnrSocketPayload): boolean {
    return !!this.activePnr && payload.pnr === this.activePnr && !!payload.data;
  }

  handlePnrUpdate(payload: PnrSocketPayload) {
    if (this.shouldApplyUpdate(payload)) {
      this.callbacks.onPnrUpdate(payload.data);
    }
  }

  handleAutoRefreshStopped(payload: PnrSocketPayload) {
    if (payload?.pnr === this.activePnr) {
      this.callbacks.onAutoRefreshStopped(payload);
    }
  }

  attach(socket: PnrSocketLike): () => void {
    const onConnect = () => {
      this.resubscribeOnConnect();
      this.callbacks.onConnect?.();
    };
    const onUpdate = (data: PnrSocketPayload) => this.handlePnrUpdate(data);
    const onStopped = (data: PnrSocketPayload) => this.handleAutoRefreshStopped(data);
    const onDisconnect = () => this.callbacks.onDisconnect?.();

    socket.on('connect', onConnect);
    socket.on('pnr:update', onUpdate);
    socket.on('pnr:autoRefreshStopped', onStopped);
    socket.on('disconnect', onDisconnect);

    return () => {
      socket.off('connect', onConnect);
      socket.off('pnr:update', onUpdate);
      socket.off('pnr:autoRefreshStopped', onStopped);
      socket.off('disconnect', onDisconnect);
    };
  }
}